CREATE DATABASE IF NOT EXISTS atelier CHARACTER SET utf8mb4;
USE atelier;
DROP TABLE IF EXISTS banners, user_tokens, wishlist_items, addresses, audit_log, reviews, order_items, orders, products, brands, categories, coupons, users;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('customer','admin') NOT NULL DEFAULT 'customer',token_version INT NOT NULL DEFAULT 0,failed_attempts TINYINT NOT NULL DEFAULT 0,locked_until DATETIME NULL,email_verified_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,slug VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE brands(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE products(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,description TEXT,price DECIMAL(10,2) NOT NULL,compare_at DECIMAL(10,2) NULL,category_id INT NOT NULL,brand_id INT NOT NULL,stock INT NOT NULL DEFAULT 0,color VARCHAR(9) NOT NULL DEFAULT '#1F3A32',badge VARCHAR(30) NULL,rating DECIMAL(2,1) NOT NULL DEFAULT 4.5,reviews_count INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id),FOREIGN KEY(brand_id) REFERENCES brands(id),INDEX(category_id),INDEX(brand_id),INDEX(price));
CREATE TABLE orders(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,status ENUM('pending','paid','shipped','delivered','cancelled') NOT NULL DEFAULT 'pending',subtotal DECIMAL(10,2) NOT NULL,shipping DECIMAL(10,2) NOT NULL,total DECIMAL(10,2) NOT NULL,discount DECIMAL(10,2) NOT NULL DEFAULT 0,coupon_code VARCHAR(30) NULL,ship_name VARCHAR(100) NOT NULL,ship_address VARCHAR(200) NOT NULL,ship_city VARCHAR(80) NOT NULL,ship_postal VARCHAR(20) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX(user_id),INDEX(status));
CREATE TABLE order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,product_id INT NOT NULL,name VARCHAR(150) NOT NULL,price DECIMAL(10,2) NOT NULL,quantity INT NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE reviews(id INT AUTO_INCREMENT PRIMARY KEY,product_id INT NOT NULL,user_id INT NOT NULL,rating TINYINT NOT NULL,body TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(product_id,user_id),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE coupons(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) NOT NULL UNIQUE,percent_off TINYINT NOT NULL,min_subtotal DECIMAL(10,2) NOT NULL DEFAULT 0,max_uses INT NULL,used_count INT NOT NULL DEFAULT 0,expires_at DATE NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE audit_log(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(50) NOT NULL,detail VARCHAR(255),ip VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),INDEX(action));
CREATE TABLE user_tokens(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,type ENUM('verify','reset') NOT NULL,token_hash CHAR(64) NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(token_hash),INDEX(user_id,type));
CREATE TABLE addresses(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,label VARCHAR(40) NOT NULL DEFAULT 'Home',name VARCHAR(100) NOT NULL,line1 VARCHAR(200) NOT NULL,city VARCHAR(80) NOT NULL,postal VARCHAR(20) NOT NULL,is_default BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(user_id));
CREATE TABLE wishlist_items(user_id INT NOT NULL,product_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,product_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE banners(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(120) NOT NULL,subtitle VARCHAR(200) NOT NULL DEFAULT '',link VARCHAR(200) NOT NULL DEFAULT '/shop',active BOOLEAN NOT NULL DEFAULT TRUE,sort_order INT NOT NULL DEFAULT 0);
